contracts=[]
for s in ['architecture-engineer','security-reviewer','spec-engineer','typescript-engineer','node-engineer','typescript-test-engineer','nextjs','hono-engineer','supabase-engineer']:
 p=W/'skills'/s/'SKILL.md';text=p.read_text();version=re.search(r'source-version:\s*([^\n]+)',text)
